-- Skema awal D1 untuk Admin Panel JGS (disiapkan, belum dipakai website publik).
CREATE TABLE IF NOT EXISTS settings      (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS pages         (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT UNIQUE NOT NULL, title TEXT NOT NULL, seo_title TEXT, seo_description TEXT, published INTEGER DEFAULT 1, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sections      (id INTEGER PRIMARY KEY AUTOINCREMENT, page_id INTEGER NOT NULL REFERENCES pages(id), key TEXT NOT NULL, content_json TEXT NOT NULL, sort_order INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS services      (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL, summary TEXT, body TEXT, image_key TEXT, sort_order INTEGER DEFAULT 0, published INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS business_focus(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT, image_key TEXT, sort_order INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS clients       (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, logo_key TEXT, confirmed INTEGER DEFAULT 0, sort_order INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS portfolio     (id INTEGER PRIMARY KEY AUTOINCREMENT, client_id INTEGER REFERENCES clients(id), title TEXT NOT NULL, body TEXT, image_key TEXT);
CREATE TABLE IF NOT EXISTS news          (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT UNIQUE NOT NULL, title TEXT NOT NULL, body TEXT, cover_key TEXT, published_at TEXT);
CREATE TABLE IF NOT EXISTS navigation    (id INTEGER PRIMARY KEY AUTOINCREMENT, label TEXT NOT NULL, href TEXT NOT NULL, sort_order INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS media         (id INTEGER PRIMARY KEY AUTOINCREMENT, r2_key TEXT UNIQUE NOT NULL, alt TEXT, mime TEXT, size INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS contact_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, company TEXT, phone TEXT NOT NULL, email TEXT NOT NULL, service TEXT, message TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
